/// The category of each item as ulsitem.h notes it (0 ctype, 1 time,
/// 2 numeric, 3 monetary, 4 messages, 5 collate).
const ITEM_CATS: &[u8; MAXITEM] = b"1111111111111111111111111111111111111111111224430000201111124411033230021133221111311130500224411110000000000000000000044011102221111111";

/// The locale object category (LC_*) an item belongs to.
pub fn item_category(item: usize) -> usize {
    match ITEM_CATS.get(item.wrapping_sub(1)) {
        Some(b'1') => LC_TIME,
        Some(b'2') => LC_NUMERIC,
        Some(b'3') => LC_MONETARY,
        Some(b'4') => LC_MESSAGES,
        Some(b'5') => LC_COLLATE,
        _ => LC_CTYPE,
    }
}

/// An item by its name (case-insensitive).
pub fn item_by_name(name: &str) -> Option<usize> {
    ITEM_NAMES.iter().position(|n| n.eq_ignore_ascii_case(name)).map(|i| i + 1)
}

/// UCS-2 of an ASCII/Latin-1 string.
pub fn ucs(s: &str) -> Vec<u16> {
    s.chars().map(|c| c as u16).collect()
}

/// A UCS-2 string up to its NUL.
///
/// # Safety
/// `p` points to a NUL-terminated UCS-2 string.
pub unsafe fn from_ptr<'a>(p: *const u16) -> &'a [u16] {
    let mut n = 0;
    unsafe {
        while *p.add(n) != 0 {
            n += 1;
        }
        core::slice::from_raw_parts(p, n)
    }
}

/// An ASCII name from UCS-2 (None if a character is not ASCII).
pub fn ascii(u: &[u16]) -> Option<String> {
    u.iter().map(|&c| (c < 0x80).then_some(c as u8 as char)).collect()
}

/// Characters a locale name may contain besides letters and digits.
const NAME_PUNCT: &[u8] = b"_-!@#$%&*+";

/// Valid locale names: 1-31 printable ASCII letters, digits and `_-!@#$%&*+`.
pub fn valid_name(name: &[u16]) -> bool {
    !name.is_empty()
        && name.len() < 32
        && name.iter().all(|&c| c < 0x80 && ((c as u8).is_ascii_alphanumeric() || NAME_PUNCT.contains(&(c as u8))))
}

// ---- system locales -------------------------------------------------------

/// Number of system locales.
pub fn system_count() -> usize {
    data::LOCALES.len()
}

/// A system locale's name.
pub fn system_name(i: usize) -> &'static str {
    data::LOCALES[i].0
}

/// A system locale's item (1-136) as a NUL-terminated UCS-2 string in
/// the static pool.
pub fn system_item_z(i: usize, item: usize) -> &'static [u16] {
    let off = data::LOCALES[i].1[item - 1] as usize;
    let len = data::POOL[off..].iter().position(|&c| c == 0).unwrap();
    &data::POOL[off..off + len + 1]
}

/// A system locale's item without the NUL.
pub fn system_item(i: usize, item: usize) -> &'static [u16] {
    let z = system_item_z(i, item);
    &z[..z.len() - 1]
}

/// The range of addresses of the static strings (LIBUNI's UniFreeMem
/// leaves them alone).
pub fn pool_range() -> core::ops::Range<usize> {
    let p = data::POOL.as_ptr() as usize;
    p..p + data::POOL.len() * 2
}

/// A system locale by name: case-insensitive; `C` and `POSIX` are the
/// posix locale; a code set (`.IBM-850`) or modifier (`@...`) is ignored.
pub fn find_system(name: &str) -> Option<usize> {
    let name = name.split(['.', '@']).next().unwrap_or("");
    let name = if name.eq_ignore_ascii_case("C") { "posix" } else { name };
    data::LOCALES.iter().position(|(n, _)| n.eq_ignore_ascii_case(name))
}

/// The system locale for a country code (UniMapCtryToLocale).
pub fn locale_for_country(code: u32) -> Option<usize> {
    let text = ucs(&alloc::format!("{code}"));
    (2..system_count()).find(|&i| system_item(i, 108) == text.as_slice())
}

/// The number an item's string holds: decimal, or hexadecimal digits for
/// the x items (xLocaleToken, xWinLocale), as IBM's locale_value reads
/// them. None if the string is not a number.
pub fn item_value(item: usize, s: &[u16]) -> Option<i32> {
    let s = ascii(s)?;
    if s.is_empty() {
        return None;
    }
    if ITEM_NAMES.get(item.wrapping_sub(1)).is_some_and(|n| n.starts_with('x')) {
        return u32::from_str_radix(&s, 16).ok().map(|v| v as i32);
    }
    s.parse::<i32>().ok()
}

/// The string UniSetUserLocaleItem stores for a number: decimal, or for
/// the x items upper-case hex of 4 or 8 digits with a leading 0 before a
/// letter.
pub fn value_string(item: usize, v: i32) -> String {
    if ITEM_NAMES.get(item.wrapping_sub(1)).is_some_and(|n| n.starts_with('x')) {
        let h = alloc::format!("{:08X}", v as u32);
        let h = h.strip_prefix("0000").unwrap_or(&h);
        return if h.as_bytes()[0] > b'9' { alloc::format!("0{h}") } else { String::from(h) };
    }
    alloc::format!("{v}")
}

/// An item's category digit as ulsitem.h and LOCALE.DLL's
/// locale_itemcategory give it (0 ctype, 1 time, 2 numeric, 3 monetary,
/// 4 messages, 5 collate).
pub fn item_category_digit(item: usize) -> Option<u8> {
    ITEM_CATS.get(item.wrapping_sub(1)).map(|c| c - b'0')
}

// ---- user locales ---------------------------------------------------------

/// A user locale: a name, the system locale it is based on, and the
/// items it changes.
#[derive(Clone, Debug, PartialEq)]
pub struct UserLocale {
    pub name: String,
    pub base: usize,
    pub items: Vec<(usize, Vec<u16>)>,
}

/// A locale by name: a user locale (index in [`UserLocales::list`]) or a
/// system locale.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Locale {
    User(usize),
    System(usize),
}

/// The user locales of `\LANGUAGE\LOCALE\USER.LOC`, and whether they
/// changed since they were read or written.
#[derive(Clone, Debug, Default)]
pub struct UserLocales {
    pub list: Vec<UserLocale>,
    pub changed: bool,
}

/// Unicode of a byte of a code page (rs2's NLS tables; controls stay
/// controls).
pub fn cp_to_ucs(cp: u16, b: u8) -> u16 {
    if b < 0x20 || b == 0x7f {
        return b as u16;
    }
    match codepage(cp) {
        Some(t) => t[b as usize],
        None => b as u16,
    }
}

/// The byte of a code page for a character, if it has one.
pub fn ucs_to_cp(cp: u16, c: u16) -> Option<u8> {
    if c < 0x20 || c == 0x7f {
        return Some(c as u8);
    }
    match codepage(cp) {
        Some(t) => (0x20..=0xff).find(|&b| b != 0x7f && t[b] == c).map(|b| b as u8),
        None => (c < 0x100).then_some(c as u8),
    }
}

/// A single-byte code page table: Unicode for bytes 0-255.
pub fn codepage(cp: u16) -> Option<&'static [u16; 256]> {
    nls::CODEPAGES.iter().find(|(n, _)| *n == cp).map(|(_, t)| t)
}

/// DBCS lead byte ranges of a double-byte code page.
pub fn dbcs_ranges(cp: u16) -> Option<&'static [(u8, u8)]> {
    nls::DBCS.iter().find(|(n, _)| *n == cp).map(|(_, r)| *r)
}

fn hex_digit(c: u8) -> Option<u16> {
    (c as char).to_digit(16).map(|d| d as u16)
}

impl UserLocales {
    /// Parse USER.LOC: a `[codepage N]` line (850 if missing) for the
    /// bytes above 0x7F, then per locale `[locale NAME BASE]` and lines
    /// `item = "value"` where `[hex]` is a character and `[[` a `[`.
    pub fn parse(text: &[u8]) -> UserLocales {
        let mut ul = UserLocales::default();
        let mut cp = 850;
        for line in text.split(|&b| b == b'\n' || b == b'\r') {
            let line: Vec<u8> = line.iter().map(|&b| if b == b'\t' { b' ' } else { b }).collect();
            let t = trim(&line);
            if t.is_empty() {
                continue;
            }
            if t[0] == b'[' && t.last() == Some(&b']') {
                let inner = core::str::from_utf8(&t[1..t.len() - 1]).unwrap_or("");
                let mut w = inner.split_ascii_whitespace();
                match w.next() {
                    Some(k) if k.eq_ignore_ascii_case("codepage") => {
                        cp = w.next().and_then(|n| n.parse().ok()).unwrap_or(850);
                    }
                    Some(k) if k.eq_ignore_ascii_case("locale") => {
                        let Some(name) = w.next() else { continue };
                        let base = w.next().unwrap_or(name);
                        if let Some(b) = find_system(base) {
                            ul.list.retain(|l| !l.name.eq_ignore_ascii_case(name));
                            ul.list.push(UserLocale { name: name.into(), base: b, items: Vec::new() });
                        }
                    }
                    _ => {}
                }
                continue;
            }
            let Some(eq) = t.iter().position(|&b| b == b'=') else { continue };
            let key = core::str::from_utf8(trim(&t[..eq])).unwrap_or("");
            let mut val = trim(&t[eq + 1..]);
            if val.len() >= 2 && val[0] == b'"' && val[val.len() - 1] == b'"' {
                val = &val[1..val.len() - 1];
            }
            let item = item_by_name(key).or_else(|| key.parse().ok().filter(|&i| (1..=MAXITEM).contains(&i)));
            if let (Some(item), Some(l)) = (item, ul.list.last_mut()) {
                let v = unescape(val, cp);
                l.items.retain(|(i, _)| *i != item);
                l.items.push((item, v));
            }
        }
        ul
    }

    /// USER.LOC text (code page 850), as IBM's LIBUNI writes it: only the
    /// items that differ from the base locale.
    pub fn serialize(&self) -> Vec<u8> {
        let mut o = Vec::new();
        o.extend_from_slice(b"[codepage 850]\r\n");
        for l in &self.list {
            o.extend_from_slice(b"\r\n[locale ");
            o.extend_from_slice(l.name.as_bytes());
            o.push(b' ');
            o.extend_from_slice(system_name(l.base).as_bytes());
            o.extend_from_slice(b"]\r\n");
            let mut items: Vec<&(usize, Vec<u16>)> = l.items.iter().collect();
            items.sort_by_key(|(i, _)| *i);
            for (item, v) in items {
                if v.as_slice() == system_item(l.base, *item) {
                    continue;
                }
                let name = ITEM_NAMES[item - 1];
                o.extend_from_slice(b"    ");
                o.extend_from_slice(name.as_bytes());
                o.resize(o.len() + 19usize.saturating_sub(name.len()), b' ');
                o.extend_from_slice(b" = \"");
                escape(v, &mut o);
                o.extend_from_slice(b"\"\r\n");
            }
        }
        o
    }

    /// A user locale by name (case-insensitive).
    pub fn find_user(&self, name: &str) -> Option<usize> {
        self.list.iter().position(|l| l.name.eq_ignore_ascii_case(name))
    }

    /// A locale by name: user locales first (they override system locales
    /// of the same name).
    pub fn find(&self, name: &str) -> Option<Locale> {
        let n = name.split(['.', '@']).next().unwrap_or("");
        self.find_user(n).map(Locale::User).or_else(|| find_system(name).map(Locale::System))
    }

    /// A locale's item (1-136); `system` skips user overrides
    /// (LOCI_NOUSEROVERRIDE).
    pub fn item(&self, l: Locale, item: usize, system: bool) -> &[u16] {
        match l {
            Locale::System(i) => system_item(i, item),
            Locale::User(u) => {
                let ul = &self.list[u];
                match ul.items.iter().find(|(i, _)| *i == item) {
                    Some((_, v)) if !system => v,
                    _ => system_item(ul.base, item),
                }
            }
        }
    }

    /// UniMakeUserLocale: a user locale `name` based on `base`. A system
    /// locale's name may only be used for a locale based on it (its
    /// override). An existing user locale is replaced when `force` (the
    /// base name given with 0xFF00 set on its characters), otherwise it is
    /// ULS_NOOP for the same base and ULS_INVALID for another one.
    pub fn make(&mut self, name: &[u16], base: &str, force: bool) -> i32 {
        if !valid_name(name) {
            return ULS_INVALID;
        }
        let name = ascii(name).unwrap();
        let b = match self.find(base) {
            Some(Locale::System(s)) => s,
            Some(Locale::User(u)) => self.list[u].base,
            None => return ULS_NOMATCH,
        };
        if let Some(s) = find_system(&name)
            && s != b
        {
            return ULS_BADOBJECT;
        }
        if let Some(u) = self.find_user(&name) {
            if force {
                self.list[u].base = b;
                self.list[u].items.clear();
                self.changed = true;
                return ULS_SUCCESS;
            }
            return if self.list[u].base == b { ULS_NOOP } else { ULS_INVALID };
        }
        self.list.push(UserLocale { name, base: b, items: Vec::new() });
        self.changed = true;
        ULS_SUCCESS
    }

    /// UniSetUserLocaleItem with the value as UCS-2.
    pub fn set_item(&mut self, name: &str, item: usize, value: &[u16]) -> i32 {
        if !(1..=MAXITEM).contains(&item) {
            return ULS_INVALID;
        }
        let u = match self.find(name) {
            Some(Locale::User(u)) => u,
            Some(Locale::System(_)) => return ULS_BADOBJECT,
            None => return ULS_NOMATCH,
        };
        if self.item(Locale::User(u), item, false) == value {
            return ULS_SUCCESS;
        }
        let l = &mut self.list[u];
        l.items.retain(|(i, _)| *i != item);
        l.items.push((item, value.to_vec()));
        self.changed = true;
        ULS_SUCCESS
    }

    /// UniDeleteUserLocale.
    pub fn delete(&mut self, name: &str) -> i32 {
        match self.find(name) {
            Some(Locale::User(u)) => {
                self.list.remove(u);
                self.changed = true;
                ULS_SUCCESS
            }
            Some(Locale::System(_)) => ULS_INVALID,
            None => ULS_NOMATCH,
        }
    }

    /// UniQueryLocaleList: NUL-separated names ending with an empty one
    /// (at most `cch` characters with it). `flags` 1: the system locales,
    /// 2: the user locales, 0 or 3: both, then only the user locales that
    /// are not overrides of system locales.
    pub fn locale_list(&self, flags: u32, cch: usize) -> Result<Vec<u16>, i32> {
        let mut o = Vec::new();
        let mut add = |name: &str| -> Result<(), i32> {
            if o.len() + name.len() + 1 + 1 > cch {
                return Err(ULS_BUFFERFULL);
            }
            o.extend(name.bytes().map(|b| b as u16));
            o.push(0);
            Ok(())
        };
        let both = flags == 0 || flags & 3 == 3;
        if flags == 0 || flags & 1 != 0 {
            for i in 0..system_count() {
                add(system_name(i))?;
            }
        }
        if flags == 0 || flags & 2 != 0 {
            for l in &self.list {
                if both && find_system(&l.name).is_some() {
                    continue;
                }
                add(&l.name)?;
            }
        }
        o.push(0);
        Ok(o)
    }
}

fn trim(b: &[u8]) -> &[u8] {
    let s = b.iter().position(|&c| c != b' ' && c != 0).unwrap_or(b.len());
    let e = b.iter().rposition(|&c| c != b' ' && c != 0).map_or(s, |e| e + 1);
    &b[s..e]
}

/// USER.LOC value text to UCS-2.
fn unescape(v: &[u8], cp: u16) -> Vec<u16> {
    let mut o = Vec::new();
    let mut i = 0;
    while i < v.len() {
        let b = v[i];
        if b == b'[' {
            if v.get(i + 1) == Some(&b'[') {
                o.push(b'[' as u16);
                i += 2;
                continue;
            }
            if let Some(e) = v[i + 1..].iter().position(|&c| c == b']') {
                let hex = &v[i + 1..i + 1 + e];
                if !hex.is_empty() && hex.len() <= 4 && hex.iter().all(|c| c.is_ascii_hexdigit()) {
                    o.push(hex.iter().fold(0, |a, &c| a * 16 + hex_digit(c).unwrap()));
                    i += e + 2;
                    continue;
                }
            }
        }
        o.push(if b < 0x80 { b as u16 } else { cp_to_ucs(cp, b) });
        i += 1;
    }
    o
}

/// UCS-2 to USER.LOC value text: printable ASCII as is, Latin-1 letters
/// in code page 850, `[` as `[[` and anything else as `[hex]`.
fn escape(v: &[u16], o: &mut Vec<u8>) {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    for &c in v {
        if (0x20..0x7f).contains(&c) && c != b'"' as u16 && c != b'[' as u16 {
            o.push(c as u8);
        } else if c == b'[' as u16 {
            o.extend_from_slice(b"[[");
        } else if let (0xa0..=0xff, Some(b)) = (c, ucs_to_cp(850, c)) {
            o.push(b);
        } else {
            o.push(b'[');
            let digits = if c > 0xfff { 4 } else if c > 0xff { 3 } else { 2 };
            for k in (0..digits).rev() {
                o.push(HEX[(c >> (k * 4)) as usize & 0xf]);
            }
            o.push(b']');
        }
    }
}

// ---- names ----------------------------------------------------------------

/// UniQueryLanguageName: the name of language `lang` in language
/// `isolang` (the native name when they are the same, otherwise English,
/// the names rs2's tables have).
pub fn language_name(lang: &str, isolang: &str) -> Option<&'static [u16]> {
    let l = (2..system_count()).find(|&i| system_name(i)[..2].eq_ignore_ascii_case(lang))?;
    Some(system_item(l, if lang.eq_ignore_ascii_case(isolang) { 104 } else { 103 }))
}

/// UniQueryCountryName: the name of country `country` in language
/// `isolang` (from the locale for that language and country if there is
/// one, otherwise the English name).
pub fn country_name(country: &str, isolang: &str) -> Option<&'static [u16]> {
    let in_ctry = |i: usize| system_name(i).len() >= 5 && system_name(i)[3..5].eq_ignore_ascii_case(country);
    let isolang = &isolang[..isolang.len().min(2)];
    if let Some(l) = (2..system_count()).find(|&i| in_ctry(i) && system_name(i)[..2].eq_ignore_ascii_case(isolang)) {
        return Some(system_item(l, 107));
    }
    (2..system_count()).find(|&i| in_ctry(i)).map(|l| system_item(l, 105))
}

// ---- UniLconv -------------------------------------------------------------

/// The monetary sign and symbol positions of a UniLconv from iCurrency
/// and iNegCurr: (p_cs_precedes, p_sep_by_space, n_cs_precedes,
/// n_sep_by_space, p_sign_posn, n_sign_posn, os2_mondecpt).
pub fn lconv_positions(icurrency: i32, inegcurr: i32) -> [i16; 7] {
    let (pcs, psep, dec) = match icurrency {
        0 => (1, 0, 0),
        1 => (0, 0, 1),
        2 => (1, 1, 2),
        _ => (0, 1, 3),
    };
    let (ncs, nsep, nsign) = match inegcurr {
        0 => (1, 0, 0),
        1 => (1, 0, 3),
        2 => (1, 0, 4),
        3 => (1, 0, 2),
        4 => (0, 0, 0),
        5 | 6 => (0, 0, 2),
        7 => (0, 0, 4),
        8 => (0, 1, 2),
        9 => (1, 1, 3),
        10 => (0, 1, 4),
        11 | 12 => (1, 1, 1),
        13 => (0, 1, 2),
        14 => (1, 1, 0),
        _ => (0, 1, 0),
    };
    [pcs, psep, ncs, nsep, 1, nsign, dec]
}

// ---- strftime --------------------------------------------------------------

/// The fields of a C `struct tm`.
#[derive(Clone, Copy, Debug, Default)]
#[repr(C)]
pub struct Tm {
    pub sec: i32,
    pub min: i32,
    pub hour: i32,
    pub mday: i32,
    pub mon: i32,
    pub year: i32,
    pub wday: i32,
    pub yday: i32,
    pub isdst: i32,
}

fn push_num(o: &mut Vec<u16>, v: i32, width: usize, pad: u16) {
    let mut d = [0u16; 12];
    let mut n = v.unsigned_abs();
    let mut k = 0;
    loop {
        d[k] = b'0' as u16 + (n % 10) as u16;
        k += 1;
        n /= 10;
        if n == 0 {
            break;
        }
    }
    if v < 0 {
        o.push(b'-' as u16);
    }
    for _ in k..width {
        o.push(pad);
    }
    o.extend(d[..k].iter().rev());
}

/// Week of the year with weeks starting on `first` (0 Sunday, 1 Monday).
fn week(tm: &Tm, first: i32) -> i32 {
    (tm.yday + 7 - (tm.wday - first).rem_euclid(7)) / 7
}

/// UniStrftime: format `tm` by `fmt` with a locale's items (`item(n)`).
pub fn strftime<'a>(item: &dyn Fn(usize) -> &'a [u16], fmt: &[u16], tm: &Tm) -> Vec<u16> {
    let mut o = Vec::new();
    strftime_into(item, fmt, tm, &mut o, 0);
    o
}

fn strftime_into<'a>(item: &dyn Fn(usize) -> &'a [u16], fmt: &[u16], tm: &Tm, o: &mut Vec<u16>, depth: u32) {
    let sp = b' ' as u16;
    let zero = b'0' as u16;
    let mut i = 0;
    while i < fmt.len() {
        let c = fmt[i];
        i += 1;
        if c != b'%' as u16 || i >= fmt.len() {
            o.push(c);
            continue;
        }
        let mut f = fmt[i];
        i += 1;
        // POSIX modifiers (alternative eras and digits) are ignored.
        if (f == b'E' as u16 || f == b'O' as u16) && i < fmt.len() {
            f = fmt[i];
            i += 1;
        }
        let wday = tm.wday.rem_euclid(7) as usize;
        let mon = tm.mon.rem_euclid(12) as usize;
        let hour12 = if tm.hour % 12 == 0 { 12 } else { tm.hour % 12 };
        let sub = |o: &mut Vec<u16>, s: &[u16]| {
            if depth < 4 {
                strftime_into(item, s, tm, o, depth + 1)
            }
        };
        match f as u8 {
            b'a' => o.extend_from_slice(item(6 + wday)),
            b'A' => o.extend_from_slice(item(13 + wday)),
            b'b' | b'h' => o.extend_from_slice(item(20 + mon)),
            b'B' => o.extend_from_slice(item(32 + mon)),
            b'c' => sub(o, item(1)),
            b'C' => push_num(o, (tm.year + 1900) / 100, 2, zero),
            b'd' => push_num(o, tm.mday, 2, zero),
            b'D' => sub(o, &ucs("%m/%d/%y")),
            b'e' => push_num(o, tm.mday, 2, sp),
            b'H' => push_num(o, tm.hour, 2, zero),
            b'I' => push_num(o, hour12, 2, zero),
            b'j' => push_num(o, tm.yday + 1, 3, zero),
            b'm' => push_num(o, tm.mon + 1, 2, zero),
            b'M' => push_num(o, tm.min, 2, zero),
            b'n' => o.push(b'\n' as u16),
            b'p' => o.extend_from_slice(item(if tm.hour < 12 { 4 } else { 5 })),
            b'r' => sub(o, item(55)),
            b'R' => sub(o, &ucs("%H:%M")),
            b'S' => push_num(o, tm.sec, 2, zero),
            b't' => o.push(b'\t' as u16),
            b'T' => sub(o, &ucs("%H:%M:%S")),
            b'u' => push_num(o, if wday == 0 { 7 } else { wday as i32 }, 1, zero),
            b'U' => push_num(o, week(tm, 0), 2, zero),
            b'w' => push_num(o, wday as i32, 1, zero),
            b'W' => push_num(o, week(tm, 1), 2, zero),
            b'x' => sub(o, item(2)),
            b'X' => sub(o, item(3)),
            b'y' => push_num(o, (tm.year + 1900).rem_euclid(100), 2, zero),
            b'Y' => push_num(o, tm.year + 1900, 1, zero),
            b'Z' => {}
            b'%' => o.push(b'%' as u16),
            _ => {
                o.push(b'%' as u16);
                o.push(f);
            }
        }
    }
}

// ---- character types -------------------------------------------------------

pub const CT_UPPER: u16 = 0x0001;
pub const CT_LOWER: u16 = 0x0002;
pub const CT_DIGIT: u16 = 0x0004;
pub const CT_SPACE: u16 = 0x0008;
pub const CT_PUNCT: u16 = 0x0010;
pub const CT_CNTRL: u16 = 0x0020;
pub const CT_BLANK: u16 = 0x0040;
pub const CT_XDIGIT: u16 = 0x0080;
pub const CT_ALPHA: u16 = 0x0100;
pub const CT_ALNUM: u16 = 0x0200;
pub const CT_GRAPH: u16 = 0x0400;
pub const CT_PRINT: u16 = 0x0800;
pub const CT_NUMBER: u16 = 0x1000;
pub const CT_SYMBOL: u16 = 0x2000;
pub const CT_ASCII: u16 = 0x8000;

/// UNICTYPE: the classification UniQueryCharType returns.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
#[repr(C)]
pub struct UniCType {
    pub itype: u16,
    pub bidi: u8,
    pub charset: u8,
    pub extend: u16,
    pub codepage: u16,
}

/// The type of a UCS-2 character (Unicode properties from `core`).
pub fn char_type(uc: u16) -> UniCType {
    let Some(ch) = char::from_u32(uc as u32) else {
        return UniCType::default();
    };
    let mut t = 0;
    if ch.is_uppercase() {
        t |= CT_UPPER;
    }
    if ch.is_lowercase() {
        t |= CT_LOWER;
    }
    if ch.is_ascii_digit() {
        t |= CT_DIGIT;
    }
    if ch.is_whitespace() {
        t |= CT_SPACE;
    }
    if ch == ' ' || ch == '\t' || ch == '\u{a0}' || ch == '\u{3000}' {
        t |= CT_BLANK;
    }
    if ch.is_control() {
        t |= CT_CNTRL;
    }
    if ch.is_ascii_hexdigit() {
        t |= CT_XDIGIT;
    }
    if ch.is_alphabetic() {
        t |= CT_ALPHA;
    }
    if ch.is_numeric() {
        t |= CT_NUMBER;
    }
    if t & (CT_ALPHA | CT_DIGIT) != 0 {
        t |= CT_ALNUM;
    }
    let printable = !ch.is_control() && !matches!(uc, 0xd800..=0xdfff | 0xfff0..=0xffff | 0xe000..=0xf8ff);
    if printable {
        t |= CT_PRINT;
        if !ch.is_whitespace() {
            t |= CT_GRAPH;
            if t & (CT_ALPHA | CT_NUMBER) == 0 {
                t |= CT_PUNCT;
                if !ch.is_ascii_punctuation() && !matches!(uc, 0x2000..=0x206f | 0x3000..=0x303f | 0xa1..=0xbf) {
                    t |= CT_SYMBOL;
                }
            }
        }
    }
    if uc < 0x80 {
        t |= CT_ASCII;
    }
    let charset = match uc {
        0x41..=0x5a | 0x61..=0x7a | 0xc0..=0x24f | 0x1e00..=0x1eff => 0x02,
        0x370..=0x3ff | 0x1f00..=0x1fff => 0x05,
        0x400..=0x52f => 0x03,
        0x590..=0x5ff | 0xfb1d..=0xfb4f => 0x06,
        0x600..=0x6ff | 0xfb50..=0xfdff | 0xfe70..=0xfeff => 0x04,
        0x900..=0x97f => 0x0c,
        0xe00..=0xe7f => 0x07,
        0xe80..=0xeff => 0x12,
        0x3040..=0x309f => 0x09,
        0x30a0..=0x30ff | 0xff66..=0xff9f => 0x08,
        0x3100..=0x312f => 0x0b,
        0x1100..=0x11ff | 0x3130..=0x318f | 0xac00..=0xd7a3 => 0x0a,
        _ if t & CT_ALPHA != 0 => 0x01,
        0x20a0..=0x20cf | 0x24 | 0xa2..=0xa5 => 0x28,
        0x2190..=0x21ff => 0x25,
        0x2200..=0x22ff => 0x23,
        0x2500..=0x257f => 0x26,
        0x2010..=0x2015 | 0x2d => 0x27,
        _ => 0x00,
    };
    let rtl = matches!(charset, 0x04 | 0x06) && t & CT_ALPHA != 0;
    let bidi = if t & CT_DIGIT != 0 {
        0x03
    } else if matches!(uc, 0x660..=0x669 | 0x6f0..=0x6f9) {
        0x06
    } else if rtl {
        0x02
    } else if t & CT_ALPHA != 0 {
        0x01
    } else if uc == 0x0a || uc == 0x0d || uc == 0x2029 {
        0x08
    } else if t & CT_SPACE != 0 {
        0x0a
    } else if t & CT_GRAPH != 0 {
        0x0b
    } else {
        0x00
    };
    let mut extend = 0;
    if t & CT_ALPHA != 0 {
        extend |= 0x8000;
    }
    if t & CT_SYMBOL != 0 {
        extend |= 0x0008;
    }
    if matches!(uc, 0x300..=0x36f) {
        extend |= 0x0003;
    }
    match uc {
        0x3040..=0x309f => extend |= 0x0020,
        0x30a0..=0x30ff => extend |= 0x0010,
        0xff61..=0xffdc => extend |= 0x0040,
        0xff01..=0xff5e => extend |= 0x0080,
        0x4e00..=0x9fff | 0x3400..=0x4dbf | 0xf900..=0xfaff => extend |= 0x0100,
        _ => {}
    }
    let mut codepage = 0;
    if ucs_to_cp(437, uc).is_some() {
        codepage |= 0x0001;
    }
    if ucs_to_cp(850, uc).is_some() {
        codepage |= 0x0002;
    }
    UniCType { itype: t, bidi, charset, extend, codepage }
}

/// UniToupper / UniTolower for one UCS-2 character (unchanged when the
/// mapping is not a single BMP character).
pub fn to_upper(uc: u16) -> u16 {
    case_map(uc, true)
}

pub fn to_lower(uc: u16) -> u16 {
    case_map(uc, false)
}

fn case_map(uc: u16, upper: bool) -> u16 {
    let Some(ch) = char::from_u32(uc as u32) else { return uc };
    let m = if upper {
        let mut it = ch.to_uppercase();
        [it.next(), it.next()]
    } else {
        let mut it = ch.to_lowercase();
        [it.next(), it.next()]
    };
    match m {
        [Some(c), None] if (c as u32) < 0x10000 => c as u16,
        _ => uc,
    }
}

